function saveAuditLog(entries) {
  // Keep last 5000 entries max to prevent unbounded growth
  let trimmed = entries.slice(-5000);
  // Also enforce max file size (10MB) — drop oldest entries if too large
  let json = JSON.stringify(trimmed, null, 2);
  while (json.length > 10_000_000 && trimmed.length > 100) {
    trimmed = trimmed.slice(Math.floor(trimmed.length * 0.2)); // drop oldest 20%
    json = JSON.stringify(trimmed, null, 2);
  }
  atomicWriteText(MEMORY_LOG_PATH, json);
}

