// --- Config Management ---
function loadConfig() {
  try {
    if (fs.existsSync(CONFIG_PATH)) {
      const raw = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
      // Validate structure
      if (!raw || typeof raw !== 'object') return { projectDirs: [] };
      if (!Array.isArray(raw.projectDirs)) raw.projectDirs = [];
      // Ensure all entries are strings
      raw.projectDirs = raw.projectDirs.filter(d => typeof d === 'string');
      return raw;
    }
  } catch {}
  return { projectDirs: [] };
}

function saveConfig(config) {
  atomicWriteJson(CONFIG_PATH, config);
}

// --- Helpers ---
function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

// ── Atomic write helpers — prevents corruption on crash mid-write ─────────────
// Writes to a .tmp sibling, then renames atomically so readers never see partial data.
function atomicWriteJson(filePath, data) {
  const tmp = filePath + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(data, null, 2), 'utf-8');
  fs.renameSync(tmp, filePath);
}

