      edges.push({ from: node.reportsTo, to: node.id });
    }
  }

  // Phases in pipeline view
  const phaseList = Object.values(phases || {})
    .sort((a, b) => (a.order || 0) - (b.order || 0))
    .map((p) => ({
      id: p.id,
      label: p.label,
      description: p.description,
      color: p.color,
      agents: nodes
        .filter((n) => n.phase === p.id)
        .map((n) => ({
          id: n.id,
          name: n.name,
          title: n.title,
          model: n.model,
          description: n.description,
          level: n.level,
          yearsOfExperience: n.yearsOfExperience,
        })),
    }));

  // Departments in org view
  const departmentList = Object.values(departments || {})
    .filter((d) => d.active !== false)
    .sort((a, b) => (a.order || 0) - (b.order || 0))
    .map((d) => ({
      id: d.id,
      label: d.label,
      description: d.description,
      color: d.color,
      icon: d.icon,
      head: d.head,
      members: nodes.filter((n) => n.department === d.id),
    }));

