}

module.exports = {
  // paths (exposed for HR module)
  ORG_DIR,
  DEPARTMENTS_PATH,
  REGISTRY_PATH,

  // departments
  loadDepartments,
  saveDepartments,
  listDepartments,
  getDepartment,
  listPhases,
  getPhase,

  // registry
