function logWitnessEvent({ agent, runId, classification, meta = {} }) {
  const entry = {
    t: new Date().toISOString(),
    agent,
    runId: runId || null,
    class: classification,
    ...meta,
  };
  compactJsonlIfNeeded(WITNESS_LOG, 10000); // keep ~8,000 most recent entries
