    const d = db.getDb();
    const start = Date.now();
    const rows = d.prepare(sql).all();
    const duration = Date.now() - start;
    const columns = rows.length > 0 ? Object.keys(rows[0]) : [];
    res.json({ columns, rows: rows.slice(0, 500), total: rows.length, duration });
