import { useState, useEffect } from 'react'
import { Database, Table, Play, ChevronLeft, ChevronRight, HardDrive, Search } from 'lucide-react'
import { getDbTables, getDbTable, runDbQuery, getDbStats } from '../lib/api'
import type { DbTableInfo, DbTableData, DbQueryResult, DbStats } from '../lib/api'
import { PageShell } from '../components/PageShell'
import { toast } from '../components/Toast'

export default function DatabaseExplorer() {
  const [tables, setTables] = useState<DbTableInfo[]>([])
  const [stats, setStats] = useState<DbStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [activeTable, setActiveTable] = useState<string | null>(null)
  const [tableData, setTableData] = useState<DbTableData | null>(null)
  const [tableLoading, setTableLoading] = useState(false)
  const [offset, setOffset] = useState(0)
  const [queryMode, setQueryMode] = useState(false)
  const [sql, setSql] = useState('SELECT * FROM agents LIMIT 20')
  const [queryResult, setQueryResult] = useState<DbQueryResult | null>(null)
  const [queryLoading, setQueryLoading] = useState(false)
  const [tableSearch, setTableSearch] = useState('')
  const limit = 50

  useEffect(() => {
    Promise.all([getDbTables(), getDbStats()])
      .then(([t, s]) => { setTables(t); setStats(s) })
      .catch(() => toast('error', 'Failed to load database info'))
      .finally(() => setLoading(false))
  }, [])

  const loadTable = (name: string, off = 0) => {
    setActiveTable(name)
    setOffset(off)
    setTableLoading(true)
    setQueryMode(false)
    getDbTable(name, limit, off)
      .then(setTableData)
      .catch(() => toast('error', 'Failed to load table'))
      .finally(() => setTableLoading(false))
  }

  const handleQuery = () => {
    if (!sql.trim()) return
    setQueryLoading(true)
    setQueryResult(null)
    runDbQuery(sql.trim())
      .then(r => { setQueryResult(r); setQueryMode(true); setActiveTable(null) })
      .catch(err => toast('error', err.message))
      .finally(() => setQueryLoading(false))
  }

  const totalRows = tables.reduce((s, t) => s + t.rowCount, 0)
  const filteredTables = tableSearch
    ? tables.filter(t => t.name.toLowerCase().includes(tableSearch.toLowerCase()))
    : tables

  if (loading) {
    return (
      <PageShell title="Database" subtitle="SQLite Explorer">
        <div className="flex items-center justify-center h-48">
          <div className="w-5 h-5 border-2 border-accent border-t-transparent rounded-full animate-spin" />
        </div>
      </PageShell>
    )
  }

  return (
    <PageShell title="Database" subtitle="Browse tables and run queries">
      {/* Stats bar */}
      <div className="flex items-center gap-3 mb-5 flex-wrap">
        <div className="flex items-center gap-2 px-3 py-1.5 bg-surface rounded-lg border border-border text-xs">
          <Database className="w-3.5 h-3.5 text-accent" />
          <span className="font-semibold">{stats?.tableCount}</span>
          <span className="text-text-muted">tables</span>
        </div>
        <div className="flex items-center gap-2 px-3 py-1.5 bg-surface rounded-lg border border-border text-xs">
          <Table className="w-3.5 h-3.5 text-blue-400" />
          <span className="font-semibold">{totalRows.toLocaleString()}</span>
          <span className="text-text-muted">total rows</span>
        </div>
        <div className="flex items-center gap-2 px-3 py-1.5 bg-surface rounded-lg border border-border text-xs">
          <HardDrive className="w-3.5 h-3.5 text-green-400" />
          <span className="font-semibold">{stats?.sizeMb} MB</span>
          <span className="text-text-muted">WAL mode</span>
        </div>
        <span className="text-[10px] text-text-muted font-mono ml-auto hidden md:block">{stats?.path}</span>
      </div>

      <div className="flex gap-4 min-h-[500px]">
        {/* Left: table list */}
        <div className="w-56 shrink-0 space-y-2">
          <div className="relative">
            <Search className="w-3.5 h-3.5 text-text-muted absolute left-2.5 top-1/2 -translate-y-1/2" />
            <input
              value={tableSearch}
              onChange={e => setTableSearch(e.target.value)}
              placeholder="Filter tables..."
              className="w-full bg-surface border border-border rounded-lg pl-8 pr-2 py-1.5 text-xs focus:outline-none focus:border-accent/50"
            />
          </div>
          <div className="space-y-0.5 max-h-[520px] overflow-y-auto">
            {filteredTables.map(t => (
              <button
                key={t.name}
                onClick={() => loadTable(t.name)}
                className={`w-full flex items-center justify-between px-2.5 py-2 rounded-lg text-left text-xs transition-all ${
                  activeTable === t.name
                    ? 'bg-accent/10 text-accent border border-accent/20'
                    : 'hover:bg-surface-2 text-text-secondary border border-transparent'
                }`}
              >
                <span className="font-medium truncate">{t.name}</span>
                <span className={`text-[10px] font-mono shrink-0 ml-1 ${t.rowCount > 0 ? 'text-text-muted' : 'text-text-muted/40'}`}>
                  {t.rowCount}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Right: data view */}
        <div className="flex-1 min-w-0 space-y-3">
          {/* Query input */}
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <textarea
                value={sql}
                onChange={e => setSql(e.target.value)}
                onKeyDown={e => { if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') handleQuery() }}
                placeholder="SELECT * FROM agents WHERE status = 'active' LIMIT 20"
                rows={2}
                className="w-full bg-surface border border-border rounded-lg px-3 py-2 text-xs font-mono focus:outline-none focus:border-accent/50 resize-none"
              />
              <span className="absolute bottom-1.5 right-2 text-[9px] text-text-muted">⌘+Enter to run</span>
            </div>
            <button
              onClick={handleQuery}
              disabled={queryLoading || !sql.trim()}
              className="flex items-center gap-1.5 px-4 py-2 bg-accent text-white rounded-lg text-xs font-semibold hover:bg-accent-hover disabled:opacity-40 transition-colors self-start shrink-0"
            >
              {queryLoading ? (
                <div className="w-3 h-3 border-2 border-white border-t-transparent rounded-full animate-spin" />
              ) : (
                <Play className="w-3 h-3" />
              )}
              Run
            </button>
          </div>

          {/* Results */}
          {queryMode && queryResult ? (
            <QueryResultView result={queryResult} />
          ) : tableData ? (
            <TableDataView
              data={tableData}
              loading={tableLoading}
              tableInfo={tables.find(t => t.name === activeTable)}
              onPageChange={off => loadTable(activeTable!, off)}
              offset={offset}
              limit={limit}
            />
          ) : (
            <div className="flex items-center justify-center h-64 text-text-muted text-sm">
              Select a table or run a query
            </div>
          )}
        </div>
      </div>
    </PageShell>
  )
}

function TableDataView({ data, loading, tableInfo, onPageChange, offset, limit }: {
  data: DbTableData
  loading: boolean
  tableInfo?: DbTableInfo
  onPageChange: (offset: number) => void
  offset: number
  limit: number
}) {
  const totalPages = Math.ceil(data.total / limit)
  const currentPage = Math.floor(offset / limit) + 1

  return (
    <div>
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <h3 className="text-sm font-bold">{data.table}</h3>
          <span className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">
            {data.total.toLocaleString()} rows
          </span>
          {tableInfo && (
            <span className="text-[10px] text-text-muted">
              {tableInfo.columns.length} columns
            </span>
          )}
        </div>
        {data.total > limit && (
          <div className="flex items-center gap-1.5">
            <button
              onClick={() => onPageChange(Math.max(0, offset - limit))}
              disabled={offset === 0}
              className="p-1 rounded hover:bg-surface-2 disabled:opacity-30 text-text-muted"
            >
              <ChevronLeft className="w-3.5 h-3.5" />
            </button>
            <span className="text-[10px] text-text-muted font-medium">{currentPage}/{totalPages}</span>
            <button
              onClick={() => onPageChange(offset + limit)}
              disabled={offset + limit >= data.total}
              className="p-1 rounded hover:bg-surface-2 disabled:opacity-30 text-text-muted"
            >
              <ChevronRight className="w-3.5 h-3.5" />
            </button>
          </div>
        )}
      </div>
      <DataTable columns={data.columns} rows={data.rows} loading={loading} />
    </div>
  )
}

function QueryResultView({ result }: { result: DbQueryResult }) {
  return (
    <div>
      <div className="flex items-center gap-2 mb-2">
        <span className="text-[10px] text-green-400 bg-green-500/10 px-2 py-0.5 rounded-full font-semibold">
          {result.total} row{result.total !== 1 ? 's' : ''} in {result.duration}ms
        </span>
        {result.total > 500 && (
          <span className="text-[10px] text-amber-400">Showing first 500</span>
        )}
      </div>
      <DataTable columns={result.columns} rows={result.rows} loading={false} />
    </div>
  )
}

function DataTable({ columns, rows, loading }: {
  columns: string[]
  rows: Record<string, unknown>[]
  loading: boolean
}) {
  if (loading) {
    return (
      <div className="flex items-center justify-center h-32">
        <div className="w-4 h-4 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (rows.length === 0) {
    return (
      <div className="bg-surface border border-border rounded-xl p-8 text-center text-text-muted text-xs">
        No rows
      </div>
    )
  }

  return (
    <div className="bg-surface border border-border rounded-xl overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-border bg-surface-2/50">
              {columns.map(col => (
                <th key={col} className="text-left px-3 py-2 font-semibold text-text-muted whitespace-nowrap">
                  {col}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, i) => (
              <tr key={i} className="border-b border-border/50 hover:bg-surface-2/30 transition-colors">
                {columns.map(col => {
                  const val = row[col]
                  const display = val === null ? 'NULL' : typeof val === 'object' ? JSON.stringify(val) : String(val)
                  const isNull = val === null
                  const isJson = typeof val === 'string' && (val.startsWith('{') || val.startsWith('['))
                  const isLong = display.length > 80
                  return (
                    <td
                      key={col}
                      className={`px-3 py-2 whitespace-nowrap max-w-[300px] overflow-hidden text-ellipsis ${
                        isNull ? 'text-text-muted/40 italic' : isJson ? 'font-mono text-[10px] text-blue-400' : 'text-text'
                      }`}
                      title={isLong ? display : undefined}
                    >
                      {isLong ? display.slice(0, 80) + '...' : display}
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

