// Update a row (auto-snapshots old data for revert)
app.put('/api/db/table/:name/:pk', rateLimit('write'), (req, res) => {
  try {
    const tableName = req.params.name.replace(/[^a-zA-Z0-9_]/g, '');
    const pkValue = req.params.pk;
    const updates = req.body;
    if (!updates || typeof updates !== 'object' || Object.keys(updates).length === 0) {
      return res.status(400).json({ error: 'No fields to update' });
    }
    const row = db.updateRow(tableName, pkValue, updates);
    res.json({ ok: true, row });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// Delete a row (auto-snapshots for revert)
app.delete('/api/db/table/:name/:pk', rateLimit('write'), (req, res) => {
  try {
    const tableName = req.params.name.replace(/[^a-zA-Z0-9_]/g, '');
    res.json(db.deleteRow(tableName, req.params.pk));
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// Get change history
app.get('/api/db/changes', rateLimit('read'), (req, res) => {
  try {
    const { table, limit } = req.query;
    res.json(db.getChanges(table, parseInt(limit) || 100));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Revert a change
app.post('/api/db/revert/:id', rateLimit('write'), (req, res) => {
  try {
    res.json(db.revertChange(parseInt(req.params.id)));
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

