// ── Database Lifecycle ──────────────────────────────────────────────────────

function getDb() {
  if (_db) return _db;
  fs.mkdirSync(DB_DIR, { recursive: true });
  _db = new Database(DB_PATH);
  _db.pragma('journal_mode = WAL');
  _db.pragma('foreign_keys = ON');
  _db.pragma('busy_timeout = 5000');
  _db.pragma('synchronous = NORMAL');
  runMigrations(_db);
  return _db;
}

function close() {
  if (_db) { _db.close(); _db = null; }
}

