12	// ── Security: CORS — restrict to localhost origins ────────────────────────────
13	const ALLOWED_ORIGINS = new Set([
14	  'http://localhost:3847',
15	  'http://localhost:5173',   // Vite dev
16	  'http://localhost:3000',
17	  'http://localhost:8080',
18	  'http://127.0.0.1:3847',
19	  'http://127.0.0.1:5173',
20	  'http://127.0.0.1:3000',
21	  'http://127.0.0.1:8080',
22	]);
23	
24	app.use((req, res, next) => {
25	  const origin = req.headers.origin;
26	  if (origin && ALLOWED_ORIGINS.has(origin)) {
27	    res.header('Access-Control-Allow-Origin', origin);
28	  } else if (!origin) {
29	    // Same-origin or non-browser client — no CORS header needed
30	  }
31	  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
32	  res.header('Access-Control-Allow-Headers', 'Content-Type');
33	  if (req.method === 'OPTIONS') return res.sendStatus(204);
34	  next();
35	});
36	
37	// ── Security: Localhost-only guard ────────────────────────────────────────────
38	app.use((req, res, next) => {
39	  // Webhook triggers are accessible externally (validated by secret)
40	  if (req.path.startsWith('/api/webhooks/trigger/')) return next();
41	  const ip = req.ip || req.connection?.remoteAddress || '';
42	  const isLocal = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
43	  if (!isLocal) {
44	    return res.status(403).json({ error: 'Polyglot is local-only' });
45	  }
46	  next();
47	});
48	
49	// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
50	const rateLimitMap = new Map();
51	const RATE_LIMIT_WINDOW = 60_000; // 1 minute
52	const RATE_LIMITS = {
53	  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
54	  write: 60,   // file writes, creates, deletes — 60/min
55	  read: 200,   // reads, listings — 200/min
56	};
57	
58	function rateLimit(tier) {
59	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
60	  return (req, res, next) => {
61	    const key = `${tier}:${req.ip}`;
62	    const now = Date.now();
63	    let entry = rateLimitMap.get(key);
64	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
65	      entry = { start: now, count: 0 };
66	      rateLimitMap.set(key, entry);
67	    }
68	    entry.count++;
69	    if (entry.count > max) {
70	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
71	    }
72	    next();
73	  };
74	}
75	
76	// Cleanup stale entries every 5 minutes
77	setInterval(() => {
78	  const now = Date.now();
79	  for (const [key, entry] of rateLimitMap) {
80	    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
81	  }
82	}, 300_000);
83	
84	// ── Security: Helmet-like headers ────────────────────────────────────────────
85	app.use((req, res, next) => {
86	  res.setHeader('X-Content-Type-Options', 'nosniff');
87	  res.setHeader('X-Frame-Options', 'DENY');
88	  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
89	  next();
90	});
91	
92	app.use(express.json({ limit: '2mb' }));
93	// Serve built React frontend, fallback to legacy public/
94	const distPath = path.join(__dirname, '..', 'public-dist');
95	const legacyPath = path.join(__dirname, '..', 'public');
96	const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
97	app.use(express.static(staticPath));
