101	const CONFIG_PATH = path.join(__dirname, '..', 'config.json'); // used for startup log only
102	
103	// ── Agent Run Tracker — foundation for analytics ────────────────────────────
104	// Data now stored in SQLite via db.js — no race conditions, no write queue needed.
105	function loadAgentRuns() { return db.loadAgentRuns(); }
106	function saveAgentRuns() { /* no-op: SQLite handles persistence */ }
107	function estimateTokens(text) {
108	  return Math.ceil((text || '').length / 4);
109	}
110	function estimateCost(inputTokens, outputTokens) {
111	  return (inputTokens * 3 + outputTokens * 15) / 1_000_000;
112	}
113	function logAgentRun(entry) {
