const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
const matter = require('gray-matter');
const cron = require('node-cron');
const backup = require('./backup');
const db = require('./db');

const app = express();

// ── Security: CORS — restrict to localhost origins ────────────────────────────
const ALLOWED_ORIGINS = new Set([
  'http://localhost:3847',
  'http://localhost:5173',   // Vite dev
  'http://localhost:3000',
  'http://localhost:8080',
  'http://127.0.0.1:3847',
  'http://127.0.0.1:5173',
  'http://127.0.0.1:3000',
  'http://127.0.0.1:8080',
]);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin && ALLOWED_ORIGINS.has(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  } else if (!origin) {
    // Same-origin or non-browser client — no CORS header needed
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// ── Security: Localhost-only guard ────────────────────────────────────────────
app.use((req, res, next) => {
  // Webhook triggers are accessible externally (validated by secret)
  if (req.path.startsWith('/api/webhooks/trigger/')) return next();
  const ip = req.ip || req.connection?.remoteAddress || '';
  const isLocal = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
  if (!isLocal) {
    return res.status(403).json({ error: 'Polyglot is local-only' });
  }
  next();
});

// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
const rateLimitMap = new Map();
const RATE_LIMIT_WINDOW = 60_000; // 1 minute
const RATE_LIMITS = {
  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
  write: 60,   // file writes, creates, deletes — 60/min
  read: 200,   // reads, listings — 200/min
};

function rateLimit(tier) {
  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
  return (req, res, next) => {
    const key = `${tier}:${req.ip}`;
    const now = Date.now();
    let entry = rateLimitMap.get(key);
    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
      entry = { start: now, count: 0 };
      rateLimitMap.set(key, entry);
    }
    entry.count++;
    if (entry.count > max) {
      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
    }
    next();
  };
}

// Cleanup stale entries every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of rateLimitMap) {
    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
  }
}, 300_000);

// ── Security: Helmet-like headers ────────────────────────────────────────────
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

app.use(express.json({ limit: '2mb' }));
// Serve built React frontend, fallback to legacy public/
const distPath = path.join(__dirname, '..', 'public-dist');
const legacyPath = path.join(__dirname, '..', 'public');
const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
app.use(express.static(staticPath));

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');
const CONFIG_PATH = path.join(__dirname, '..', 'config.json'); // used for startup log only

// ── Agent Run Tracker — foundation for analytics ────────────────────────────
// Data now stored in SQLite via db.js — no race conditions, no write queue needed.
function loadAgentRuns() { return db.loadAgentRuns(); }
function saveAgentRuns() { /* no-op: SQLite handles persistence */ }
function estimateTokens(text) {
  return Math.ceil((text || '').length / 4);
}
function estimateCost(inputTokens, outputTokens) {
  return (inputTokens * 3 + outputTokens * 15) / 1_000_000;
}
function logAgentRun(entry) {
  const inputTokens = estimateTokens(entry.prompt || '');
  const outputTokens = estimateTokens(entry.output || '');
  const run = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    agentName: entry.agentName || 'unknown',
    prompt: (entry.prompt || '').slice(0, 200),
    source: entry.source || 'unknown',
    timestamp: new Date().toISOString(),
    duration: entry.duration || 0,
    status: entry.status || 'success',
    promptChars: (entry.prompt || '').length,
    outputChars: (entry.output || '').length,
    estimatedTokens: inputTokens + outputTokens,
    estimatedCost: estimateCost(inputTokens, outputTokens),
    error: entry.error || null,
    metadata: entry.metadata || {},
  };
  try { db.insertAgentRun(run); } catch (err) { console.error('[logAgentRun] DB insert failed:', err.message); }

  // Auto-learn from every run (ruflo-inspired SONA pattern)
  try {
    recordLearning(run.agentName, entry.taskType || 'general', {
      success: run.status === 'success',
      duration: run.duration,
      tokens: run.estimatedTokens,
      cost: run.estimatedCost,
    });
  } catch (err) {
    console.error('[logAgentRun] Failed to record learning:', err.message);
  }

  return run;
}

// ── Schedules — cron-based agent runs (SQLite) ──────────────────────────────
function loadSchedules() { return db.loadSchedules(); }
function saveSchedules(list) { try { db.saveSchedules(list); } catch (err) { console.error('[saveSchedules] DB write failed:', err.message); throw err; } }

// ── Webhooks — external trigger endpoints (SQLite) ──────────────────────────
function loadWebhooks() { return db.loadWebhooks(); }
function saveWebhooks(list) { try { db.saveWebhooks(list); } catch (err) { console.error('[saveWebhooks] DB write failed:', err.message); throw err; } }

// ── Playground History — persisted test results (SQLite) ────────────────────
function loadPlaygroundHistory() { return db.loadPlaygroundHistory(); }
function savePlaygroundHistory(list) { try { db.savePlaygroundHistory(list); } catch (err) { console.error('[savePlaygroundHistory] DB write failed:', err.message); throw err; } }

function loadGlobalSettings() {
  const fp = path.join(CLAUDE_DIR, 'settings.json');
  try { if (fs.existsSync(fp)) return JSON.parse(fs.readFileSync(fp, 'utf-8')); } catch {} return {};
}

// --- Security: Name & Path Validation ---
function isValidName(name) {
  return /^[a-zA-Z0-9_-]+$/.test(name) && !name.includes('..');
}

function validateName(req, res, next) {
  if (!isValidName(req.params.name)) {
    return res.status(400).json({ error: 'Invalid name. Only letters, numbers, hyphens and underscores allowed.' });
  }
